from pathlib import Path


def find_repo_root(start: Path) -> Path:
    """Traverse upwards to find the repository root (containing .agent/)."""
    curr = start.resolve()
    for _ in range(10):
        if (curr / ".agent").exists():
            return curr
        if curr.parent == curr:
            break
        curr = curr.parent
    return Path.cwd()
